function taxMasterLabel(value = "") {
  const labels = {
    base_price: "Base Price",
    selling_price: "Selling Price",
    inclusive: "Inclusive",
    exclusive: "Exclusive",
    percent: "%",
    flat: "Flat"
  };
  return labels[value] || value || "-";
}

const TAX_MASTER_DEFAULT_FORMULA = "(taxApplicablePrice * taxValue / (100 + taxValue))";

function taxMasterEvaluateFormula(form = $("#taxMasterForm")) {
  if (!form) return;
  const basePrice = Number(form.elements.testBasePrice?.value || 0);
  const discount = Number(form.elements.testDiscount?.value || 0);
  const sellingPrice = Number(form.elements.testSellingPrice?.value || 0);
  const taxValue = Number(form.elements.taxValue?.value || 0);
  const taxApplicability = form.elements.taxApplicability?.value || "exclusive";
  const taxType = form.elements.taxType?.value || "percent";
  const taxApplicablePrice = form.elements.taxApplicableOn?.value === "base_price" ? basePrice : sellingPrice;
  const netAfterDiscount = Math.max(0, taxApplicablePrice - discount);
  const formula = String(form.elements.formula?.value || TAX_MASTER_DEFAULT_FORMULA)
    .replace(/Tax Applicable On Price/gi, "taxApplicablePrice")
    .replace(/Tax Value/gi, "taxValue")
    .replace(/\bBase Price\b/gi, "basePrice")
    .replace(/\bSelling Price\b/gi, "sellingPrice")
    .replace(/\bDiscount\b/gi, "discount")
    .replace(/\s+x\s+/gi, " * ");
  const output = $("#taxMasterFormulaResult");
  if (!output) return;
  try {
    if (!/^[\d\s+\-*/().,_a-zA-Z]+$/.test(formula)) throw new Error("Only numbers, formula variables, and arithmetic operators are allowed.");
    const result = Function("basePrice", "discount", "sellingPrice", "taxValue", "taxApplicablePrice", `"use strict"; return (${formula});`)(
      basePrice,
      discount,
      sellingPrice,
      taxValue,
      taxApplicablePrice
    );
    if (!Number.isFinite(Number(result))) throw new Error("Formula result is not a valid number.");
    const gstAmount = Math.max(0, Number(result));
    const totalWithExclusiveTax = taxApplicability === "exclusive" ? netAfterDiscount + gstAmount : netAfterDiscount;
    output.innerHTML = `
      <span><small>GST Amount</small><b>${escapeHtml(priceMasterMoneyText(gstAmount))}</b></span>
      <span><small>Applicable Price</small><b>${escapeHtml(priceMasterMoneyText(taxApplicablePrice))}</b></span>
      <span><small>After Discount</small><b>${escapeHtml(priceMasterMoneyText(netAfterDiscount))}</b></span>
      <span><small>${escapeHtml(taxMasterLabel(taxApplicability))} ${escapeHtml(taxMasterLabel(taxType))}</small><b>${escapeHtml(priceMasterMoneyText(totalWithExclusiveTax))}</b></span>
    `;
  } catch (error) {
    output.innerHTML = `<span class="text-danger">${escapeHtml(error.message || "Invalid formula")}</span>`;
  }
}

