async function executeAdminPaymentConfirmation(id) {
  const form = $("#adminPaymentConfirmationForm");
  if (!form) return;
  const data = formObject(form);
  let proofUrl = "";
  if (data.adminPaymentProof) {
    try {
      const proof = JSON.parse(data.adminPaymentProof);
      proofUrl = proof.previewUrl || proof.url || "";
    } catch {
      proofUrl = "";
    }
  }
  if (data.response === "yes" && !String(data.referenceId || "").trim()) {
    showAlert("Enter transaction/reference ID before confirming payment.", "warning");
    return;
  }
  if (data.response === "yes" && !proofUrl) {
    showAlert("Upload admin payment proof before confirming payment.", "warning");
    return;
  }
  await api(`/operations/bookings/${id}/payment-confirmation`, {
    method: "POST",
    body: JSON.stringify({
      response: data.response === "no" ? "no" : "yes",
      referenceId: data.referenceId || "",
      note: data.note || "",
      proofUrl,
      sourceUpdateId: data.sourceUpdateId || ""
    })
  });
  closeBookingInfoModal();
  showAlert(data.response === "no" ? "Payment kept pending." : "Payment marked as paid.", data.response === "no" ? "warning" : "success");
  await loadBookings(bookingActiveTab);
}

async function executeBookingCancel(id) {
  const reason = $("#bookingCancelReasonInput")?.value?.trim();
  if (!reason || reason.length < 3) {
    showAlert("Enter cancellation reason.", "warning");
    return;
  }
  await api(`/operations/bookings/${id}/cancel`, { method: "POST", body: JSON.stringify({ reason }) });
  closeBookingInfoModal();
  showAlert("Booking cancelled successfully.", "success");
  await loadBookings(bookingActiveTab);
}

