function toggleCategoryMasterHomeDisplayControls(form = $("#categoryMasterForm")) {
  if (!form) return;
  const categoryPrice = (form.elements.homeDisplayMode?.value || "category") === "categoryPrice";
  const grid = (form.elements.priceDisplayMode?.value || "row") === "grid";
  const customImageSize = (form.elements.categoryImageSizeMode?.value || "default") === "custom";
  const priceControls = form.querySelector("[data-category-price-display-controls]");
  const gridControls = form.querySelector("[data-category-price-grid-controls]");
  const imageSizeModeControls = form.querySelector("[data-category-image-size-mode-controls]");
  const imageSizeControls = form.querySelector("[data-category-image-size-controls]");
  if (imageSizeModeControls) imageSizeModeControls.classList.toggle("d-none", categoryPrice);
  if (imageSizeControls) imageSizeControls.classList.toggle("d-none", categoryPrice || !customImageSize);
  if (form.elements.categoryImageHeight) form.elements.categoryImageHeight.disabled = categoryPrice || !customImageSize;
  if (form.elements.categoryImageWidth) form.elements.categoryImageWidth.disabled = categoryPrice || !customImageSize;
  if (!customImageSize || categoryPrice) {
    if (form.elements.categoryImageHeight) form.elements.categoryImageHeight.value = "0";
    if (form.elements.categoryImageWidth) form.elements.categoryImageWidth.value = "0";
  }
  if (priceControls) priceControls.classList.toggle("d-none", !categoryPrice);
  if (gridControls) gridControls.classList.toggle("d-none", !categoryPrice || !grid);
}

